# Generated by the MCRI team.
#
# Variant observation counts, stage 2: replace the affected-status-only dictionary with
# `seqrdb_counted_sample_dict`, which also carries the per-individual deduplication and
# exclusion signals, and rebuild the entries -> project_gt_stats materialized views to
# honour them.
#
# Design notes:
#  * Every flag is an EXCLUSION signal (0 = count it) and every lookup passes an explicit
#    default of 0. A sample missing from Postgres, a forgotten dictGetOrDefault or a wrong
#    default therefore all resolve to COUNTING the sample rather than silently dropping it.
#  * The dictionary keys off `Sample.sample_id`, not `Individual.individual_id`. The old
#    `seqrdb_affected_status_dict` assumed the VCF sample ID equals the individual's
#    external ID; those are distinct fields and are not guaranteed equal.
#  * `seqrdb_affected_status_dict` is intentionally left in place. Nothing references it
#    once this migration runs, but leaving it keeps the migration cheap to reverse.
#  * Every operation is re-runnable. ClickHouse DDL is not transactional, so if any later
#    statement fails, the objects already created survive. Django does not record the
#    migration, and the next `migrate` retries it from the top against that partial state.
from string import Template

from django.db import migrations

from settings import DATABASES

# OR REPLACE (rather than a separate DROP) so a retry after a partial failure succeeds
# without tripping ClickHouse's dependency checks on objects that may already use it.
COUNTED_SAMPLE_DICT = Template("""
CREATE OR REPLACE DICTIONARY `seqrdb_counted_sample_dict`
(
    `family_guid` String,
    `sampleId` String,
    `individual_guid` String,
    `affected` String,
    `is_excluded` UInt8,
    `is_superseded` UInt8,
    `is_duplicate_assay` UInt8
)
PRIMARY KEY family_guid, sampleId
SOURCE(POSTGRESQL(
    NAME 'seqr_postgres_named_collection'
    DATABASE $database
    QUERY 'select family_guid, sample_id, individual_guid, affected, is_excluded, is_superseded, is_duplicate_assay from mcri_counted_sample'
))
LIFETIME(MIN 0 MAX 0)
LAYOUT(COMPLEX_KEY_HASHED());
""").substitute(database=DATABASES['default']['NAME'])

DROP_COUNTED_SAMPLE_DICT = 'DROP DICTIONARY IF EXISTS `seqrdb_counted_sample_dict`'

# `counted` gates every aggregate. Defaults of 0 mean "not excluded" / "not superseded",
# so anything the dictionary does not know about still contributes.
COUNTED_EXPR = """
    dictGetOrDefault('seqrdb_counted_sample_dict', 'is_excluded',   (family_guid, calls.sampleId), 0) = 0
    AND dictGetOrDefault('seqrdb_counted_sample_dict', 'is_superseded', (family_guid, calls.sampleId), 0) = 0
      AS counted
"""

ENTRIES_TO_PROJECT_GT_STATS = Template("""
CREATE MATERIALIZED VIEW `$reference_genome/$dataset_type/entries_to_project_gt_stats_mv`
TO `$reference_genome/$dataset_type/project_gt_stats`
AS SELECT
    project_guid,
    key,
    dictGetOrDefault('seqrdb_counted_sample_dict', 'affected', (family_guid, calls.sampleId), 'U') affected,
    $columns
FROM (
    SELECT *, $counted_expr
    FROM `$reference_genome/$dataset_type/entries`
    ARRAY JOIN calls
)
GROUP BY $groupby_columns
""")

# Restores the pre-migration definition (clickhouse_search/0016) on reverse.
LEGACY_ENTRIES_TO_PROJECT_GT_STATS = Template("""
CREATE MATERIALIZED VIEW `$reference_genome/$dataset_type/entries_to_project_gt_stats_mv`
TO `$reference_genome/$dataset_type/project_gt_stats`
AS SELECT
    project_guid,
    key,
    dictGetOrDefault('seqrdb_affected_status_dict', 'affected', (family_guid, calls.sampleId), 'U') affected,
    $columns
FROM `$reference_genome/$dataset_type/entries`
ARRAY JOIN calls
GROUP BY $groupby_columns
""")

SNV_INDEL_COLUMNS = [
    'sample_type',
    "sumIf(sign, calls.gt = 'REF' AND counted) ref_samples",
    "sumIf(sign, calls.gt = 'HET' AND counted) het_samples",
    "sumIf(sign, calls.gt = 'HOM' AND counted) hom_samples",
]
MITO_COLUMNS = [
    'sample_type',
    "sumIf(sign, calls.hl == '0' AND counted) ref_samples",
    "sumIf(sign, calls.hl > '0' AND calls.hl < '0.95' AND counted) het_samples",
    "sumIf(sign, calls.hl >= '0.95' AND counted) hom_samples",
]
SV_COLUMNS = [
    "sumIf(sign, calls.gt = 'REF' AND counted) ref_samples",
    "sumIf(sign, calls.gt = 'HET' AND counted) het_samples",
    "sumIf(sign, calls.gt = 'HOM' AND counted) hom_samples",
]
# The 0016 definitions, for the reverse operation.
LEGACY_COLUMNS = {
    'SNV_INDEL': [c.replace(' AND counted', '') for c in SNV_INDEL_COLUMNS],
    'MITO': [c.replace(' AND counted', '') for c in MITO_COLUMNS],
    'SV': [c.replace(' AND counted', '') for c in SV_COLUMNS],
}

SAMPLE_TYPE_GROUP_BY = 'project_guid, key, sample_type, affected'
DATASET_TYPES = [
    ('GRCh37', 'SNV_INDEL', SNV_INDEL_COLUMNS, SAMPLE_TYPE_GROUP_BY),
    ('GRCh38', 'SNV_INDEL', SNV_INDEL_COLUMNS, SAMPLE_TYPE_GROUP_BY),
    ('GRCh38', 'MITO', MITO_COLUMNS, SAMPLE_TYPE_GROUP_BY),
    ('GRCh38', 'SV', SV_COLUMNS, 'project_guid, key, affected'),
]


def _mv_operations():
    operations = []
    for reference_genome, dataset_type, columns, groupby_columns in DATASET_TYPES:
        drop = f'DROP TABLE IF EXISTS `{reference_genome}/{dataset_type}/entries_to_project_gt_stats_mv`'
        forward = ENTRIES_TO_PROJECT_GT_STATS.substitute(
            reference_genome=reference_genome,
            dataset_type=dataset_type,
            counted_expr=COUNTED_EXPR,
            columns=',\n    '.join(columns),
            groupby_columns=groupby_columns,
        )
        backward = LEGACY_ENTRIES_TO_PROJECT_GT_STATS.substitute(
            reference_genome=reference_genome,
            dataset_type=dataset_type,
            columns=',\n    '.join(LEGACY_COLUMNS[dataset_type]),
            groupby_columns=groupby_columns,
        )
        # Drop and create share one operation so that each direction starts from a clean
        # slate. As two operations, reversing would run the legacy CREATE before the DROP
        # and fail because the view already exists.
        operations.append(migrations.RunSQL([drop, forward], [drop, backward], hints={'clickhouse': True}))
    return operations


class Migration(migrations.Migration):

    dependencies = [
        ('clickhouse_search', '0023_add_sex_dict'),
    ]

    operations = [
        migrations.RunSQL(
            COUNTED_SAMPLE_DICT, DROP_COUNTED_SAMPLE_DICT, hints={'clickhouse': True},
        ),
        *_mv_operations(),
    ]
